    //  - j is the fast-varying dimension (matches C's path[i][j] layout).
    //  - Parallelize across rows (i) and vectorize across columns (j).
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

