    Param<int> k_param("k");

    Var i("i"), j("j");

    // --- Micro-kernel factorization for better locality ---------------------
    //
    // Naïve translation of the step would read path[i][k] and path[k][j]
    // at every (i,j), which means:
    //   - path[i][k] (a column) is fetched n times per row (strided loads),
    //   - path[k][j] (a row) is fetched n times per column,
    // leading to a lot of redundant memory traffic.
    //
    // We instead factor the computation as:
    //   col_k(i) = path[i][k]
    //   row_k(j) = path[k][j]
    //   step(i,j) = min(path[i][j], col_k(i) + row_k(j))
