    //   C: path[i][k] -> path_param(k, i)
    //   C: path[k][j] -> path_param(j, k)
    col_k(i) = path_param(k_param, i);   // column k: path[i][k]
    row_k(j) = path_param(j, k_param);   // row k:    path[k][j]

    Expr current = path_param(j, i);     // path[i][j]
    Expr via_k   = col_k(i) + row_k(j);  // path[i][k] + path[k][j]
    floyd_step(j, i) = Halide::min(current, via_k);

