    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1) Schedules for the factored 1D helpers.
    //
    // They are O(n) per k and tiny compared to the O(n^2) main step,
    // so a simple vectorization is enough; we keep them out-of-line
    // with compute_root() so each is computed once per k.
    col_k
        .compute_root()
        .vectorize(i, vec_width);

    row_k
        .compute_root()
        .vectorize(j, vec_width);

    // 2) Schedule for the 2D Floyd–Warshall step.
    //
    // We tile the (j,i) space into reasonably cache-friendly tiles,
    // parallelize over tiles, and vectorize across the j dimension
    // (contiguous in memory: Buffer(x=j, y=i)).
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi"), tile("tile");

    // Tunable tile sizes (can be adjusted for different cache hierarchies).
    const int tile_j = 128; // columns per tile
    const int tile_i = 32;  // rows per tile

    floyd_step
        // Tile the j (x) and i (y) dimensions.
        .tile(j, i, xo, yo, xi, yi, tile_j, tile_i)
        // Fuse the tile coordinates into a single parallel dimension to avoid
        // nested parallel loops and to distribute tiles across cores.
        .fuse(xo, yo, tile)
        .parallel(tile)
        // Vectorize across the inner j coordinate (contiguous in memory).
        .vectorize(xi, vec_width)
        // The loop order inside each tile is: yi (rows) outside, xi (cols) inside.
        ;

