#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <algorithm>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (defines N and DATA_TYPE)
#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Tunable scheduling constants for the Floyd–Warshall step.
// These can be changed to better match a particular CPU/cache layout.
static constexpr int TILE_I          = 32;  // tile height  (rows, i-dimension)
static constexpr int TILE_J_FACTOR   = 8;   // tile width as (vector_width * TILE_J_FACTOR)

/**
 * Initialize the path matrix.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       path[i][j] = i*j%7+1;
 *       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
 *          path[i][j] = 999;
 *     }
 *
 * C array path[i][j] is mapped to Buffer(j, i).
 */
static void init_array(int n, Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    // Base value: i * j % 7 + 1
    Expr base = cast<num_t>((i * j % 7) + 1);

    // Condition for setting to 999
    Expr sum  = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    // Map C path[i][j] -> Halide path(j, i)
    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             base);

    // Simple, but scheduled to make good use of CPU parallelism and SIMD:
    //
    //  * j is the innermost, contiguous dimension (stride-1 in memory),
    //    so we vectorize across j.
    //  * we split i into outer/inner parts and parallelize across the
    //    outer part, giving coarse-grain parallelism over rows.
    {
        Target target = get_jit_target_from_environment();
        int vec_width = Halide::natural_vector_size<num_t>(target);

        Var io("io"), ii("ii");
        init_path
            .split(i, io, ii, 64)      // 64 rows per parallel task
            .parallel(io)              // parallel over row blocks
            .vectorize(j, vec_width);  // SIMD across contiguous columns
    }

    // Realize into the provided buffer. Buffer layout is (x=j, y=i).
    init_path.realize(path);
}

/**
 * Print the path matrix (mainly to prevent dead-code elimination
 * and for optional correctness checking).
 *
 * Mirrors the PolyBench print_array semantics, but prints to stderr.
 */
static void print_array(int n, Buffer<num_t, 2> path) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // path[i][j] -> path(j, i)
            std::cerr << path(j, i) << '\n';
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to: DATA_TYPE path[N][N]
    // We use two buffers for double-buffered Floyd–Warshall.
    //
    // Layout: Buffer(x=j, y=i)
    //   - dimension 0 (x=j) has stride 1  -> contiguous columns
    //   - dimension 1 (y=i) has stride n  -> separate rows
    Buffer<num_t, 2> path0(n, n);
    Buffer<num_t, 2> path1(n, n);

    // Initialize data into path0
    init_array(n, path0);

    // Halide parameters and pipeline for a single Floyd–Warshall step.
    //
    // We follow the recommended DP translation pattern:
    //   For each k:
    //     path[i][j] = min(path[i][j], path[i][k] + path[k][j])
    //
    // Implemented as a Func that reads from an ImageParam (current path)
    // and a scalar Param k, then executed from a host-side loop with
    // double-buffering.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func floyd_step("floyd_step");

    // Mapping between C and Halide indices:
    //
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k, i)
    //   C: path[k][j] -> path_param(j, k)
    //
    // For fixed k, we compute over (i,j):
    Expr current = path_param(j, i);
    Expr via_k   = path_param(k_param, i) + path_param(j, k_param);

    floyd_step(j, i) = Halide::min(current, via_k);

    // Scheduling for floyd_step:
    //
    //  * j is the contiguous dimension, so we vectorize across j.
    //  * i is the outer (row) dimension; we tile it and parallelize
    //    across row tiles.
    //  * We use tiling to improve cache locality across (i,j) and to
    //    give coarse-grain work units to the parallel runtime.
    {
        Target target = get_jit_target_from_environment();
        int vec_width = Halide::natural_vector_size<num_t>(target);

        // Choose tile sizes based on the natural vector width.
        const int tile_j = std::max(vec_width * TILE_J_FACTOR, vec_width);
        const int tile_i = TILE_I;

        Var jo("jo"), io("io"), ji("ji"), ii("ii");

        floyd_step
            // Tile over (j, i): outer tiles (jo, io), inner coords (ji, ii).
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            // Vectorize across the inner j-dimension (contiguous).
            .vectorize(ji, vec_width)
            // Parallelize across row-tiles for good multi-core utilization.
            .parallel(io);
    }

    // Bind initial data and compile the step once.
    // Subsequent calls to realize() will reuse the compiled code.
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop

    {
        Target target = get_jit_target_from_environment();
        floyd_step.compile_jit(target);
    }

    // Double-buffering pointers
    Buffer<num_t, 2> *current_path = &path0;
    Buffer<num_t, 2> *next_path    = &path1;

    // Time only the Floyd–Warshall kernel (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        // Bind the current path and the iteration index k.
        //
        // Note: k_param is a Halide Param<int>, so each call to
        // realize(floyd_step) sees the current value of k without
        // recompilation.
        path_param.set(*current_path);
        k_param.set(k);

        // Compute the next path matrix for this k:
        //   next_path(i,j) = min(current_path(i,j),
        //                        current_path(i,k) + current_path(k,j))
        floyd_step.realize(*next_path);

        // Swap buffers for the next iteration
        std::swap(current_path, next_path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // The final result is in *current_path
    Buffer<num_t, 2> &path = *current_path;

    // Optional printing to prevent dead-code elimination and for debugging.
    // This mirrors the style from example/gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        print_array(n, path);
    }

    // Print kernel execution time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
